/**
 * Loader for baked animation textures (VAT/OAT). Given a base URL (or a URL ending with .exr or .json),
 * it loads the EXR texture and its paired JSON metadata, then constructs and returns an initialized
 * AnimationBakeMixer.
 *
 * URL resolution rules:
 * - If the URL ends with .exr, the JSON URL is derived by replacing with .json.
 * - If the URL ends with .json, the EXR URL is derived by replacing with .exr.
 * - Otherwise, "<url>.exr" and "<url>.json" are used.
 *
 * ```js
 * import { AnimationBakeLoader } from '@three-blocks/core';
 *
 * const loader = new AnimationBakeLoader();
 * loader.load('/files/baked_vat', (mixers, meta) => {
 *   const clips = Array.isArray(mixers) ? mixers : [ mixers ];
 *   const metaList = Array.isArray(meta) ? meta : [ meta ];
 *   clips.forEach((mixer, index) => {
 *     const info = metaList[ index ] ?? {};
 *     const instanceCount = info.instances?.length ?? info.idCount ?? 0;
 *     console.log('Instances in clip', index, instanceCount);
 *     mixer.play();
 *   });
 * });
 *
 * // or use the async variant
 * const clipMixers = await loader.loadAsync('/files/baked_vat');
 * const mixers = Array.isArray(clipMixers) ? clipMixers : [ clipMixers ];
 * mixers.forEach((mixer) => mixer.setConfig({ loop: false }).play());
 * ```
 *
 * @class AnimationBakeLoader
 * @short Loader that fetches EXR + JSON baked animation data and returns an initialized AnimationBakeMixer.
 * @category Animation
 * @extends Loader
 * @tags WebGPU, WebGL
 * @see AnimationBakeMixer
 */
export class AnimationBakeLoader {
    /**
     * @param {THREE.LoadingManager} [manager]
     */
    constructor(manager?: THREE.LoadingManager);
    /**
     * Load an EXR and its paired JSON metadata and return an initialized AnimationBakeMixer.
     *
     * @param {string} url - Base URL or .exr/.json URL.
     * @param {function(AnimationBakeMixer, any)=} onLoad - Callback fired after the EXR and metadata are loaded.
     * @param {function(any)=} onProgress - Progress callback invoked with loader events.
     * @param {function(any)=} onError - Error callback invoked when load fails.
     */
    load(url: string, onLoad?: ((arg0: AnimationBakeMixer, arg1: any) => any) | undefined, onProgress?: ((arg0: any) => any) | undefined, onError?: ((arg0: any) => any) | undefined): void;
    _resolveBaseUrls(url: any): {
        exrUrl: any;
        jsonUrl: any;
    };
    _resolveUrlWithManager(target: any): any;
    _normalizeMetaEntry(entry: any): any;
    _expandCompactMeta(compact: any): any;
    _resolveTextureReference(entry: any, resolvedExrUrl: any, jsonBase: any, entryIndex: any, totalEntries: any): any;
    _loadTextureForEntry(loader: any, entry: any, { resolvedExrUrl, jsonBase, entryIndex, totalEntries, stepIndex, totalSteps, reportStep, onProgress, textureCache }: {
        resolvedExrUrl: any;
        jsonBase: any;
        entryIndex: any;
        totalEntries: any;
        stepIndex: any;
        totalSteps: any;
        reportStep: any;
        onProgress: any;
        textureCache: any;
    }): Promise<any>;
    /**
     * Promise-based variant of load.
     * @param {string} url
     * @param {function(any)=} onProgress - Optional progress callback invoked with loader events.
     * @return {Promise<AnimationBakeMixer>} Promise that resolves with the initialized mixer.
     */
    loadAsync(url: string, onProgress?: ((arg0: any) => any) | undefined): Promise<AnimationBakeMixer>;
}
import { AnimationBakeMixer } from './AnimationBakeMixer.js';
